diff --git a/store.js b/store.js
index fcb5a96..6a73bd7 100644
--- a/store.js
+++ b/store.js
@@ -1 +1,28 @@
-const fs=require('node:fs');exports.read=()=>JSON.parse(fs.readFileSync('customers.json','utf8'));exports.write=rows=>fs.writeFileSync('customers.json',JSON.stringify(rows));
+const fs = require('node:fs');
+
+const readRows = () => JSON.parse(fs.readFileSync('customers.json', 'utf8'));
+const saveRows = rows => fs.writeFileSync('customers.json', JSON.stringify(rows));
+
+const withName = customer => {
+  if (Object.hasOwn(customer, 'name') || !Object.hasOwn(customer, 'display_name')) {
+    return customer;
+  }
+  return { ...customer, name: customer.display_name };
+};
+
+exports.read = () => readRows().map(withName);
+
+exports.write = rows => saveRows(rows.map(customer => {
+  const { display_name, ...current } = withName(customer);
+  return current;
+}));
+
+exports.migrate = () => {
+  const rows = readRows();
+  const migrated = rows.map(withName);
+  // Keep legacy fields for rollback; ordinary writes use only the new field.
+  if (migrated.some((customer, index) => customer !== rows[index])) {
+    saveRows(migrated);
+  }
+  return migrated;
+};

